import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

/**
 * Comprehensive Wait For A Duration Test
 *
 * This flow demonstrates all three duration types in similar flow logic patterns:
 * 1. explicit_duration - Wait for a specific duration
 * 2. relative_duration - Wait relative to a datetime (before/after)
 * 3. percentage_duration - Wait for a percentage of time until a datetime
 */
Flow(
    {
        $id: Now.ID['test_wait_for_a_duration_comprehensive'],
        name: 'Test-Wait-For-A-Duration-Comprehensive',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        {
            $id: Now.ID['test_wait_for_a_duration_comprehensive_trigger'],
        },
        {
            table: 'incident',
            condition: '^EQ',
            run_on_extended: 'false',
            run_flow_in: 'any',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // Test 1: Explicit Duration in forEach -> if
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
            {
                annotation: 'Test explicit duration',
                $id: Now.ID['test_wait_duration_foreach_1'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.active, 'boolean')}=true`,
                        annotation: 'Check if active',
                        $id: Now.ID['test_wait_duration_if_1'],
                    },
                    () => {
                        wfa.flowLogic.waitForADuration({
                            $id: Now.ID['test_wait_duration_explicit_1'],
                            duration: '1970-01-01 10:00:00',
                            durationType: 'explicit_duration',
                            schedule: '491670c6d7011200f2d224837e61038a',
                        })
                    }
                )
            }
        )

        // Test 2: Relative Duration in forEach -> if
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.work_notes_list, 'array.string'),
            {
                annotation: 'Test relative duration',
                $id: Now.ID['test_wait_duration_foreach_2'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=1`,
                        annotation: 'Check if priority is 1',
                        $id: Now.ID['test_wait_duration_if_2'],
                    },
                    () => {
                        wfa.flowLogic.waitForADuration({
                            $id: Now.ID['test_wait_duration_relative_1'],
                            duration: '1970-01-01 01:00:00',
                            durationType: 'relative_duration',
                            relativeOperator: 'after',
                            relativeDatetime: '2025-09-04 00:00:00',
                            schedule: '245b31e3672322004792adab9485ef9c',
                        })
                    }
                )
            }
        )

        // Test 3: Percentage Duration in forEach -> if
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
            {
                annotation: 'Test percentage duration',
                $id: Now.ID['test_wait_duration_foreach_3'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.additional_assignee_list, 'reference')}ISNOTEMPTY`,
                        annotation: 'Check if assignee list is not empty',
                        $id: Now.ID['test_wait_duration_if_3'],
                    },
                    () => {
                        wfa.flowLogic.waitForADuration({
                            $id: Now.ID['test_wait_duration_percentage_1'],
                            durationType: 'percentage_duration',
                            percentage: 12,
                            percentageDatetime: '2025-09-12 00:00:00',
                            schedule: '245b31e3672322004792adab9485ef9c',
                        })
                    }
                )
            }
        )

        // Test 4: Nested forEach with Explicit Duration
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.work_notes_list, 'array.string'),
            {
                annotation: 'Outer loop for nested test',
                $id: Now.ID['test_wait_duration_foreach_4'],
            },
            () => {
                wfa.flowLogic.forEach(
                    wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
                    {
                        annotation: 'Inner loop for nested test',
                        $id: Now.ID['test_wait_duration_foreach_5'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.active, 'boolean')}=false`,
                                annotation: 'Check if not active',
                                $id: Now.ID['test_wait_duration_if_4'],
                            },
                            () => {
                                wfa.flowLogic.waitForADuration({
                                    $id: Now.ID['test_wait_duration_explicit_2'],
                                    duration: '1970-01-01 05:30:00',
                                    durationType: 'explicit_duration',
                                    schedule: '491670c6d7011200f2d224837e61038a',
                                })
                            }
                        )
                    }
                )
            }
        )

        // Test 5: Relative Duration with 'before' operator in if -> forEach
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=2`,
                annotation: 'Check if priority is 2',
                $id: Now.ID['test_wait_duration_if_5'],
            },
            () => {
                wfa.flowLogic.forEach(
                    wfa.dataPill(_params.trigger.current.work_notes_list, 'array.string'),
                    {
                        annotation: 'Test relative duration with before operator',
                        $id: Now.ID['test_wait_duration_foreach_6'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.business_impact, 'string')}ISNOTEMPTY`,
                                annotation: 'Check if business impact exists',
                                $id: Now.ID['test_wait_duration_if_6'],
                            },
                            () => {
                                wfa.flowLogic.waitForADuration({
                                    $id: Now.ID['test_wait_duration_relative_2'],
                                    duration: '1970-01-01 02:00:00',
                                    durationType: 'relative_duration',
                                    relativeOperator: 'before',
                                    relativeDatetime: '2025-12-31 23:59:59',
                                    schedule: '245b31e3672322004792adab9485ef9c',
                                })
                            }
                        )
                    }
                )
            }
        )

        // Test 6: Nested if with Percentage Duration
        wfa.flowLogic.forEach(
            wfa.dataPill(_params.trigger.current.additional_assignee_list, 'array.string'),
            {
                annotation: 'Test nested if with percentage duration',
                $id: Now.ID['test_wait_duration_foreach_7'],
            },
            () => {
                wfa.flowLogic.if(
                    {
                        condition: `${wfa.dataPill(_params.trigger.current.active, 'boolean')}=true`,
                        annotation: 'Check if active (outer)',
                        $id: Now.ID['test_wait_duration_if_7'],
                    },
                    () => {
                        wfa.flowLogic.if(
                            {
                                condition: `${wfa.dataPill(_params.trigger.current.priority, 'string')}=3`,
                                annotation: 'Check if priority is 3 (nested)',
                                $id: Now.ID['test_wait_duration_if_8'],
                            },
                            () => {
                                wfa.flowLogic.waitForADuration({
                                    $id: Now.ID['test_wait_duration_percentage_2'],
                                    durationType: 'percentage_duration',
                                    percentage: 50,
                                    percentageDatetime: '2026-01-01 00:00:00',
                                    schedule: '491670c6d7011200f2d224837e61038a',
                                })
                            }
                        )
                    }
                )
            }
        )
    }
)
